UPDATE public.spots SET access = '{"shore": true, "boat": true, "ramp": "Big Rock Boat Ramp is the main launch; Ken Forde Park (2501 S. Island Hwy) and McIvor Park also have ramps", "parking": "Trailer parking at Big Rock; the City acquired adjoining land in late 2025 to roughly double it and improve traffic circulation", "facilities": ["Boat ramps", "Beach access", "Washrooms (seasonal at some parks)", "Picnic tables", "Trails", "Interpretive centre at Ken Forde Park"], "notes": "The City of Campbell River publishes ramp and facility detail on individual park pages rather than a single boat-launch index. Big Rock has been through recent closures for maintenance and expansion works, so check the City''s news page before relying on it. Much of the fishery is run from charter boats out of the harbour.", "sourceUrl": "https://www.campbellriver.ca/city-services/capital-improvement-projects/big-rock-boat-ramp-phase-1"}'::jsonb, updated_at = now() WHERE slug = 'campbell-river-bc';
UPDATE public.spots SET access = '{"shore": true, "boat": true, "notes": "Japan restricts recreational fishing by foreign nationals to small-scale methods, and the limits depend on the vessel. From shore, rod and handline, landing and scoop nets, spear, clam rake and cast net are all permitted. From a vessel under 3 gross tons, rod, handline, nets and trolling are allowed but cast netting is not. On a vessel of 3 gross tons or more — which covers most Tokyo Bay charter boats — foreign nationals may only fish aboard a Japanese vessel under the control of a Japanese fisher, so a licensed charter is the practical route. Prefectural rules apply on top of the national ones. Local etiquette is enforced: keep clear of set nets and fishing gear, stay out of restricted areas within fishing ports, and take your rubbish home. Permanent residents are not treated as foreign nationals under these Acts.", "sourceUrl": "https://www.jfa.maff.go.jp/j/kanri/gaikokujin_yugyo_en.html"}'::jsonb, updated_at = now() WHERE slug = 'tokyo-bay-seabass';
